namespace NexusTelecommunicationManagementSystem.Models;

public enum ConnectionType { Broadband, DialUp, Telephone }
public enum OrderStatus { Pending, Feasible, InstallationScheduled, Connected, NotFeasible, Cancelled }
public enum ConnectionStatus { Active, TemporarilyInactive, PermanentlyInactive }
public sealed class Plan { public int Id { get; set; } public string Name { get; set; }=""; public ConnectionType ConnectionType { get; set; } public decimal Price { get; set; } public string BillingCycle { get; set; }="Monthly"; public string Description { get; set; }=""; public string Speed { get; set; }=""; public bool IsActive { get; set; }=true; public string CodePrefix=>ConnectionType switch{ConnectionType.Broadband=>"B",ConnectionType.DialUp=>"D",_=>"T"}; }
public sealed class ServiceOrder { public int Id { get; set; } public string OrderCode { get; set; }=""; public int? UserId { get; set; } public string CustomerName { get; set; }=""; public string Email { get; set; }=""; public string Contact { get; set; }=""; public string Address { get; set; }=""; public Plan Plan { get; set; }=new(); public OrderStatus Status { get; set; } public DateTime ApplicationDate { get; set; } public string FeasibilityNote { get; set; }=""; }
public sealed class Connection { public int Id { get; set; } public string AccountId { get; set; }=""; public int? UserId { get; set; } public string CustomerName { get; set; }=""; public Plan Plan { get; set; }=new(); public ConnectionStatus Status { get; set; } public DateTime ConnectedAt { get; set; } public decimal AmountDue { get; set; } }
public sealed class Bill { public int Id { get; set; } public string BillNumber { get; set; }=""; public string AccountId { get; set; }=""; public int? UserId { get; set; } public decimal Amount { get; set; } public decimal Paid { get; set; } public DateTime DueDate { get; set; } public string Status=>Paid>=Amount?"Paid":Paid>0?"Partial":"Due"; public decimal Due=>Math.Max(0,Amount-Paid); }
public sealed class NewOrderViewModel { public int PlanId { get; set; } public string FullName { get; set; }=""; public string Email { get; set; }=""; public string Contact { get; set; }=""; public string Address { get; set; }=""; }
public sealed class TrackViewModel { public string Code { get; set; }=""; public ServiceOrder? Order { get; set; } public Connection? Connection { get; set; } }
public sealed class LoginViewModel { public string Username { get; set; }=""; public string Password { get; set; }=""; public bool IsAdmin { get; set; } }
public sealed class SignupViewModel { public string Username { get; set; }=""; public string FullName { get; set; }=""; public string Email { get; set; }=""; public string Contact { get; set; }=""; public string Address { get; set; }=""; public string City { get; set; }=""; public string Password { get; set; }=""; public string ConfirmPassword { get; set; }=""; }
